// Single entry point for API types. Aliases point into schema.d.ts, generated by
// `npm run gen:api` from the real backend OpenAPI (M3). If the backend renames a
// schema, fix it here. A few backend fields are typed as plain `str` / `dict` in
// Pydantic; they are narrowed below to the values documented in
// docs/quyet-dinh/M3-api.md §2 so the UI can switch on them safely.
import type { components } from './schema';
import type { CalculationTrace } from '../planner/calculation-trace';
import type { DemandSummary } from '../planner/demand-contract';

type S = components['schemas'];

export type HealthStatus = S['Health'];
export type Me = S['Me'];
export type Meta = S['Meta'];
export type Source = S['SourceRef'];
export type ComputeState = NonNullable<Meta['compute_state']>;
export type Confidence = NonNullable<Meta['confidence']>;
export type ActionSpec = S['ActionSpec'];
export type ActionKind = ActionSpec['kind'];
export type Dist = S['Dist'];
/** Loose quantile shape accepted by <Range> (Dist, CoverHours, forecast totals). */
export type Quantiles = { p10?: number | null; p50?: number | null; p90?: number | null; mean?: number | null };
export type Freshness = S['Freshness'];
export type FreshnessSource = S['SourceFreshness'];

export type RecommendationStatus = S['RecommendationOut']['status'];
export type Deviation = 'on_track' | 'below_forecast' | 'above_forecast';

/** `recommendation` block of a /skus row (backend: RecRef, `best` typed as dict). */
export type SkuRecRef = Omit<S['RecRef'], 'status' | 'best' | 'confidence'> & {
  status: RecommendationStatus;
  best: ActionSpec | null;
  confidence: Confidence;
};

type SkuNarrowed = 'recommendation' | 'confidence' | 'compute_state' | 'deviation';
/** One row of GET /skus (backend: SkuSummary). */
export type SkuListItem = Omit<S['SkuSummary'], SkuNarrowed> & {
  recommendation: SkuRecRef | null;
  confidence: Confidence | null;
  compute_state: ComputeState | null;
  deviation: Deviation | null;
};
export type SkuDetail = Omit<S['SkuDetail'], SkuNarrowed> & Pick<SkuListItem, SkuNarrowed> & { demand?: DemandSummary };

/**
 * Fields the backend fills from Pydantic defaults (M3-mo-phong Q14, 05 §7/§9) are optional
 * here so older payloads and the fixtures stay valid: missing = the default.
 */
type Defaulted<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
/** `pause_feasible = false` → show `verdict_note` instead of "Pause tốt hơn" (05 §7.2). */
export type ZoneBar = Defaulted<S['ZoneBar'], 'pause_feasible' | 'pause_violations'>;
/** `what_if = true`: result of a run with overrides / session / own actions, never active. */
export type Recommendation = Omit<Defaulted<S['RecommendationOut'], 'runner_up_meets_goal' | 'what_if'>, 'zone_bar'> & {
  zone_bar: ZoneBar | null;
};
export type ZoneVerdict = ZoneBar['verdict'];
export type AltThreshold = S['AltThreshold'];
export type BreakevenRequest = S['BreakevenRequest'];
export type BreakevenResponse = Omit<S['BreakevenOut'], 'zone_bar'> & { zone_bar: ZoneBar | null };
export type FlipCondition = S['FlipCondition'];
export type InputsRef = S['InputsRefOut'];
/** Body of POST /scenarios/run. */
export type SimRequest = S['ScenarioRunRequest'];
/** `ScenarioRun.request`: the request as run (start, horizon filled). Re-send it to hit the cache. */
export type SimRequestEcho = S['SimRequestOut'];
export type ScenarioRun = Omit<S['ScenarioRun'], 'recommendation' | 'results'> & { recommendation: Recommendation | null; results: ScenarioResult[]; calculation_trace?: CalculationTrace | null };
/** `duplicate_of` = key of an identical, better-ranked action (e.g. pause_until_restock ≡ pause). */
export type ScenarioResult = S['ScenarioResultOut'] & { goal_units_sold?: Dist | null; goal_sku?: string | null };

/** One entry of `CampaignDetail.commitments` (backend: dict). */
export type Commitment = {
  id?: string;
  program?: string | null;
  kind: string;
  sku?: string | null;
  campaign_id?: string | null;
  value?: number | null;
  windows_local?: [number, number][] | null;
  window_start?: string | null;
  window_end?: string | null;
  text?: string | null;
};
export type CampaignDetail = S['CampaignDetail'];
export type CampaignSku = S['CampaignSku'];
export type GoalBrief = S['GoalBrief'];
export type GoalIn = S['GoalIn'];
export type GoalOut = S['GoalOut'];
export type GoalKind = GoalIn['kind'];

// Endpoints of M4 (decisions, alerts, live) are not served yet; their types are
// hand-written in ./pending until the backend publishes them.
export type { Alert, DecisionCreate, DecisionCreated, LiveStatus } from './pending';

/** Response frame for numeric results (08-api §1). */
export type Envelope<T> = {
  data: T;
  meta?: Meta;
};

/** List response with cursor pagination (08-api §1). */
export type Page<T> = Envelope<T[]> & { next_cursor?: string | null };

/** Error frame (08-api §1). FastAPI does not publish it in OpenAPI. */
export type ApiErrorBody = {
  error: { code: string; message: string; details?: Record<string, unknown> };
};
